mapper.sql:
WHERE 

    AND (L.TITLE LIKE CONCAT('%', #{q.keyword}, '%')
         OR L.ADDRESS_ROAD LIKE CONCAT('%', #{q.keyword}, '%'))


    AND L.DEAL_TYPE = #{q.dealType}


    AND L.ROOM_TYPE = #{q.roomType}


    AND L.DEPOSIT <= #{q.depositMax}


    AND L.MONTHLY_RENT <= #{q.monthlyRentMax}


    AND L.AREA_M2 >= #{q.areaMin}


    AND L.AREA_M2 <= #{q.areaMax}


    AND MBRContains(
        ST_GeomFromText(
            CONCAT('POLYGON((',
                #{q.swLng}, ' ', #{q.swLat}, ',',
                #{q.neLng}, ' ', #{q.swLat}, ',',
                #{q.neLng}, ' ', #{q.neLat}, ',',
                #{q.swLng}, ' ', #{q.neLat}, ',',
                #{q.swLng}, ' ', #{q.swLat}, '))'
            ),
            4326,
            'axis-order=long-lat'
        ),
        L.GEO_POINT
    )

mapper.select:
SELECT S3_URL FROM LISTING_IMAGES
WHERE LISTING_ID = #{listingId}
ORDER BY IS_COVER DESC, SORT_ORDER ASC

mapper.update:
UPDATE LISTINGS
SET DELETED_AT = CURRENT_TIMESTAMP, STATUS = 'DELETED'
WHERE LISTING_ID = #{listingId}
  AND HOST_USER_ID = #{hostUserId}
  AND DELETED_AT IS NULL

mapper.sql:
WHERE L.STATUS = 'ACTIVE' AND L.DELETED_AT IS NULL
AND L.DEAL_TYPE = #{q.dealType}
AND L.ROOM_TYPE = #{q.roomType}
AND MBRContains( ST_GeomFromText( CONCAT('POLYGON((', #{q.swLng}, ' ', #{q.swLat}, ',', #{q.neLng}, ' ', #{q.swLat}, ',', #{q.neLng}, ' ', #{q.neLat}, ',', #{q.swLng}, ' ', #{q.neLat}, ',', #{q.swLng}, ' ', #{q.swLat}, '))' ), 4326, 'axis-order=long-lat' ), L.GEO_POINT )

WHERE L.STATUS = 'ACTIVE' AND L.DELETED_AT IS NULL
AND L.DEAL_TYPE = #{q.dealType}
AND L.ROOM_TYPE = #{q.roomType}
AND MBRContains( ST_GeomFromText( CONCAT('POLYGON((', #{q.swLng}, ' ', #{q.swLat}, ',', #{q.neLng}, ' ', #{q.swLat}, ',', #{q.neLng}, ' ', #{q.neLat}, ',', #{q.swLng}, ' ', #{q.neLat}, ',', #{q.swLng}, ' ', #{q.swLat}, '))' ), 4326, 'axis-order=long-lat' ), L.GEO_POINT )

mapper.select:
SELECT L.LISTING_ID, L.TITLE, L.ROOM_TYPE, L.DEAL_TYPE, L.DEPOSIT, L.MONTHLY_RENT, L.AREA_M2, L.ROOM_COUNT, L.BATHROOM_COUNT, L.ADDRESS_ROAD, L.LATITUDE, L.LONGITUDE, L.VIEW_COUNT, L.STATUS, L.REJECT_REASON, (SELECT LI.S3_URL FROM LISTING_IMAGES LI WHERE LI.LISTING_ID = L.LISTING_ID ORDER BY LI.IS_COVER DESC, LI.SORT_ORDER ASC LIMIT 1) AS COVER_IMAGE_URL,
CASE WHEN F.USER_ID IS NOT NULL THEN TRUE ELSE FALSE END AS FAVORITED
FALSE AS FAVORITED
FROM LISTINGS L
LEFT JOIN FAVORITES F ON F.LISTING_ID = L.LISTING_ID AND F.USER_ID = #{viewerUserId}
ORDER BY L.CREATED_AT DESC LIMIT #{limit}
